import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/registry/erbium/ui/accordion";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/registry/erbium/ui/card";

const items = [
  {
    value: "plans",
    trigger: "What subscription plans do you offer?",
    content:
      "We offer three subscription tiers: Starter ($9/month), Professional ($29/month), and Enterprise ($99/month). Each plan includes increasing storage limits, API access, priority support, and team collaboration features.",
  },
  {
    value: "billing",
    trigger: "How does billing work?",
    content:
      "Billing occurs automatically at the start of each billing cycle. We accept all major credit cards, PayPal, and ACH transfers for enterprise customers. You'll receive an invoice via email after each payment.",
  },
  {
    value: "cancel",
    trigger: "How do I cancel my subscription?",
    content:
      "You can cancel your subscription anytime from your account settings. There are no cancellation fees or penalties. Your access will continue until the end of your current billing period.",
  },
];

export default function AccordionCard() {
  return (
    <Card className="w-full max-w-sm">
      <CardHeader>
        <CardTitle>Subscription & Billing</CardTitle>
        <CardDescription>
          Common questions about your account, plans, payments and cancellations.
        </CardDescription>
      </CardHeader>
      <CardContent>
        <Accordion defaultValue={["plans"]}>
          {items.map((item) => (
            <AccordionItem key={item.value} value={item.value}>
              <AccordionTrigger>{item.trigger}</AccordionTrigger>
              <AccordionContent>{item.content}</AccordionContent>
            </AccordionItem>
          ))}
        </Accordion>
      </CardContent>
    </Card>
  );
}

import { AccordionContent, AccordionItem, AccordionTrigger } from "@/registry/erbium/ui/accordion";

import { Button } from "@/registry/erbium/ui/button";

import { useState } from "react";

import { Accordion } from "@/registry/erbium/ui/accordion";

const accordionItems = [
  {
    value: "item-1",
    question: "Is it accessible?",
    answer: "Yes. It follows the WAI-ARIA accordion pattern.",
  },
  {
    value: "item-2",
    question: "Can I customize it?",
    answer: "Yes. You can style each part of the accordion.",
  },
  {
    value: "item-3",
    question: "Can I open multiple items?",
    answer: "Yes. Enable the multiple prop to open several items.",
  },
];

export function AccordionExample({
  multiple = false,
  bordered = false,
}: {
  multiple?: boolean;
  bordered?: boolean;
}) {
  return (
    <Accordion
      className={bordered ? "w-80 rounded-lg border px-4" : "w-80"}
      defaultValue={["item-1"]}
      multiple={multiple}
    >
      {accordionItems.map((item) => (
        <AccordionItem key={item.value} value={item.value}>
          <AccordionTrigger>{item.question}</AccordionTrigger>
          <AccordionContent>{item.answer}</AccordionContent>
        </AccordionItem>
      ))}
    </Accordion>
  );
}

export function ControlledAccordionExample() {
  const [value, setValue] = useState<string[]>(["item-1"]);

  return (
    <div className="flex w-80 flex-col gap-4">
      <Accordion multiple onValueChange={setValue} value={value}>
        {accordionItems.map((item) => (
          <AccordionItem key={item.value} value={item.value}>
            <AccordionTrigger>{item.question}</AccordionTrigger>
            <AccordionContent>{item.answer}</AccordionContent>
          </AccordionItem>
        ))}
      </Accordion>
      <div className="flex flex-wrap gap-2">
        <Button onClick={() => setValue(["item-1", "item-2"])} variant="outline">
          Open first two
        </Button>
        <Button onClick={() => setValue([])} variant="outline">
          Close all
        </Button>
      </div>
      <p className="text-muted-foreground text-sm">
        Open items: {value.length > 0 ? value.join(", ") : "None"}
      </p>
    </div>
  );
}

